ALTER TABLE `employees` ADD `employment_type` text DEFAULT 'client' NOT NULL;
ALTER TABLE `employees` ADD `processing_stage` text DEFAULT 'field_hr_draft' NOT NULL;
ALTER TABLE `employees` ADD `finalized_by` text;
ALTER TABLE `employees` ADD `finalized_at` text;
CREATE TABLE `vehicles` (`id` text PRIMARY KEY NOT NULL,`vendor_id` text NOT NULL,`registration_number` text NOT NULL,`vehicle_name` text NOT NULL,`vehicle_type` text DEFAULT 'car' NOT NULL,`current_odometer` real DEFAULT 0 NOT NULL,`permit_expiry` text,`insurance_expiry` text,`fc_expiry` text,`pollution_expiry` text,`next_service_date` text,`next_service_km` real,`tyre_changed_date` text,`tyre_changed_km` real,`last_water_wash_date` text,`last_wheel_alignment_date` text,`status` text DEFAULT 'active' NOT NULL,`remarks` text,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,FOREIGN KEY (`vendor_id`) REFERENCES `vendors`(`id`));
CREATE UNIQUE INDEX `vehicles_registration_number_unique` ON `vehicles` (`registration_number`);
CREATE TABLE `vehicle_records` (`id` text PRIMARY KEY NOT NULL,`vehicle_id` text NOT NULL,`record_date` text NOT NULL,`record_type` text NOT NULL,`trip_from` text,`trip_to` text,`purpose` text,`start_km` real,`end_km` real,`litres` real DEFAULT 0 NOT NULL,`amount` real DEFAULT 0 NOT NULL,`vendor_name` text,`next_due_date` text,`next_due_km` real,`remarks` text,`entered_by` text,`approved_by` text,`approved_at` text,`status` text DEFAULT 'draft' NOT NULL,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,FOREIGN KEY (`vehicle_id`) REFERENCES `vehicles`(`id`));
CREATE TABLE `utility_meters` (`id` text PRIMARY KEY NOT NULL,`vendor_id` text NOT NULL,`location_type` text NOT NULL,`location_name` text NOT NULL,`meter_number` text,`status` text DEFAULT 'active' NOT NULL,`remarks` text,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,FOREIGN KEY (`vendor_id`) REFERENCES `vendors`(`id`));
CREATE TABLE `eb_readings` (`id` text PRIMARY KEY NOT NULL,`meter_id` text NOT NULL,`reading_date` text NOT NULL,`reading_value` real NOT NULL,`units_consumed` real DEFAULT 0 NOT NULL,`amount` real DEFAULT 0 NOT NULL,`remarks` text,`entered_by` text,`approved_by` text,`approved_at` text,`status` text DEFAULT 'draft' NOT NULL,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,FOREIGN KEY (`meter_id`) REFERENCES `utility_meters`(`id`));
CREATE UNIQUE INDEX `eb_meter_reading_date_unique` ON `eb_readings` (`meter_id`,`reading_date`);
